            eprintln!("NODES {name}: found {found}, {} nodes", counter.used());
        };
        let mut options = json!({ "seed": "lethal-silence", "active": AI, "turn": 9 });
        if let (Some(base), Value::Object(extra)) = (options.as_object_mut(), silence_board()) {
