        count("wide", &worlds(&wide_board(), "lethal-wide", 2));
        count("silence", &worlds(scenario(options).state(), "lethal-silence", 2));
        count("slash", &[slashed_board()]);
        count("gauntlet", &[gauntlet_board()]);
    }
}
